            return float(value)
        elif isinstance(value, str):
            return float(value.replace(',', '.'))
        else:
            return None

    a_num = to_float(a)
    b_num = to_float(b)

    if a_num == b_num:
        return None
    elif a_num > b_num:
        return a
    else:
        return b

